import React from 'react';
import { render, screen, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import { useParams, useSearchParams } from 'next/navigation';
import QuoteViewerPage from './page';

// Mock modules
jest.mock('next/navigation', () => ({
  useParams: jest.fn(),
  useSearchParams: jest.fn(),
}));

jest.mock('@/components/ui/use-toast', () => ({
  useToast: () => ({
    toast: jest.fn(),
  }),
}));

jest.mock('@/components/ui/cta-banner', () => ({
  CTABanner: ({ message }: { message: string }) => <div data-testid="cta-banner">{message}</div>,
}));

// Helper to setup fetch mock
const setupFetchMock = (data: any) => {
  global.fetch = jest.fn(() =>
    Promise.resolve({
      ok: true,
      json: () => Promise.resolve(data),
    } as Response)
  );
};

describe('QuoteViewerPage - Membership Requirements', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    (useParams as jest.Mock).mockReturnValue({ token: 'test-token' });
    (useSearchParams as jest.Mock).mockReturnValue({ get: jest.fn(() => null) });
  });

  describe('Service Count Logic', () => {
    it('should show CTA banner when less than 3 services', async () => {
      const mockData = {
        quote: {
          firstName: 'John',
          lastName: 'Doe',
          email: 'john@example.com',
        },
        lineItems: [
          { id: '1', service: 'Service 1', alaCarteRate: 100, handldRate: 70, chosenFrequency: 1 },
          { id: '2', service: 'Service 2', alaCarteRate: 100, handldRate: 70, chosenFrequency: 1 },
        ],
      };

      setupFetchMock(mockData);
      render(<QuoteViewerPage />);

      await waitFor(() => {
        expect(screen.getByTestId('cta-banner')).toBeInTheDocument();
        expect(screen.getByText(/Handld Membership unlocks at 3\+ services/)).toBeInTheDocument();
      });
    });

    it('should not show CTA banner when 3 or more services', async () => {
      const mockData = {
        quote: {
          firstName: 'John',
          lastName: 'Doe',
          email: 'john@example.com',
        },
        lineItems: [
          { id: '1', service: 'Service 1', alaCarteRate: 100, handldRate: 70, chosenFrequency: 1 },
          { id: '2', service: 'Service 2', alaCarteRate: 100, handldRate: 70, chosenFrequency: 1 },
          { id: '3', service: 'Service 3', alaCarteRate: 100, handldRate: 70, chosenFrequency: 1 },
        ],
      };

      setupFetchMock(mockData);
      render(<QuoteViewerPage />);

      await waitFor(() => {
        expect(screen.queryByTestId('cta-banner')).not.toBeInTheDocument();
      });
    });

    it('should disable membership button when less than 3 services', async () => {
      const mockData = {
        quote: {
          firstName: 'John',
          lastName: 'Doe',
        },
        lineItems: [
          { id: '1', service: 'Service 1', alaCarteRate: 100, handldRate: 70, chosenFrequency: 1 },
        ],
      };

      setupFetchMock(mockData);
      render(<QuoteViewerPage />);

      await waitFor(() => {
        const membershipButton = screen.getByText(/Book Handld Membership/);
        expect(membershipButton).toBeDisabled();
        expect(membershipButton).toHaveClass('cursor-not-allowed', 'opacity-60');
      });
    });

    it('should enable membership button when 3 or more services', async () => {
      const mockData = {
        quote: {
          firstName: 'John',
          lastName: 'Doe',
        },
        lineItems: [
          { id: '1', service: 'Service 1', alaCarteRate: 100, handldRate: 70, chosenFrequency: 1 },
          { id: '2', service: 'Service 2', alaCarteRate: 100, handldRate: 70, chosenFrequency: 1 },
          { id: '3', service: 'Service 3', alaCarteRate: 100, handldRate: 70, chosenFrequency: 1 },
        ],
      };

      setupFetchMock(mockData);
      render(<QuoteViewerPage />);

      await waitFor(() => {
