              </div>
              <div className="text-sm text-green-600">
                Lock in these savings with Handld Membership!
              </div>
            </div>
          </div>
        ) : !membershipAvailable && (
          <div className="border-2 border-amber-400 bg-gradient-to-r from-amber-50 to-yellow-50 rounded-2xl p-4 text-center">
            <div className="text-amber-700 font-semibold mb-2">
              🔓 Unlock Member Savings
            </div>
