/* app/globals.css */
@tailwind base;
@tailwind components;
@tailwind utilities;

/* Brand defaults */
:root {
  --brand-cream: #FFF7E6;
  --brand-light-cream: #FFFAF0;
  --brand-navy: #2A54A1;
}

html, body {
  font-family: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
  background: var(--brand-cream);
  color: var(--brand-navy);
}

a {
  color: var(--brand-navy);
  text-decoration: none;
}

table a { text-decoration: underline; }

/* Subtle headings weight—color is inherited (navy) */
h1, h2, h3 { font-weight: 600; }

/* Brand color utilities */
.text-brand-navy { color: var(--brand-navy); }
.bg-brand-navy { background-color: var(--brand-navy); }
.bg-brand-cream { background-color: var(--brand-cream); }
.bg-brand-light-cream { background-color: var(--brand-light-cream); }
.border-brand-navy { border-color: var(--brand-navy); }

